// The docs and the exports can't drift apart (v0.1 readiness, 2026-11-26). Both directions, in pnpm check:
//   1. every export of every entry point is in docs/design/api-0.1.md's export index (generated by
//      `node tools/api-index.mjs write`, and current), and every function and constant there has a JSDoc summary;
//   2. every API the docs name exists: imports from @efs/sdk entry points in code blocks, the names in the
//      README's entry-point table, `efs.…`, `efs.lens.…` and `writer.…` members, and every `name(…)` in inline code
//      (an export, a member of a client, writer, journal view or replay, an @efs/fixture function, or a name listed in
//      NOT_SDK with what it is). The examples import from the packed tarballs and run in CI, so a name they use that
//      is gone fails there. api-0.1 §11 (the questions as asked) is history and is not checked.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  API_DOC,
  exportIndex,
  isValue,
  renderIndex,
  withIndex,
} from "../../../tools/api-index.mjs";
import { createWriter, memoryJournal, openJournal } from "../src/actions/index.ts";
import { createEfs } from "../src/client.ts";
import { createRecorder, createReplay, createRpcReplay } from "../src/testing/index.ts";

const ROOT = join(import.meta.dirname, "../../..");
const index = exportIndex();
const exported = (entry: string) => new Set((index[entry] ?? []).map((r) => r.name));
const allExports = new Set(Object.values(index).flatMap((rows) => rows.map((r) => r.name)));

/** The documents checked, without the generated index and the marked history. */
const DOCS = [
  "README.md",
  "packages/sdk/README.md",
  "docs/design/api-0.1.md",
  "docs/design/tags-0.1.md",
  ...readdirSync(join(ROOT, "examples"))
    .filter((d) => {
      try {
        readFileSync(join(ROOT, "examples", d, "README.md"));
        return true;
      } catch {
        return false;
      }
    })
    .map((d) => `examples/${d}/README.md`),
];
const strip = (text: string) =>
  text
    .replace(/<!-- export-index:start[\s\S]*?<!-- export-index:end -->/g, "")
    .replace(/<!-- history:start[\s\S]*?<!-- history:end -->/g, "");
const docs = DOCS.map((path) => ({ path, text: strip(readFileSync(join(ROOT, path), "utf8")) }));

/** Members of the objects the docs call methods on, read from real instances (no chain is contacted). */
async function members() {
  const deployment = JSON.parse(
    readFileSync(join(import.meta.dirname, "../fixtures/rpc/deployment.json"), "utf8"),
  );
  const efs = createEfs({ rpcs: ["http://127.0.0.1:9/"], deployment });
  const writer = await createWriter(efs, {
    authorizer: {
      kind: "local",
      profile: "direct",
      account: {
        address: "0x1111111111111111111111111111111111111111",
        signTransaction: async () => "0x",
      },
    },
    journal: memoryJournal(),
  });
  const transcript = {
    schema: "efs-sdk-rpc-transcript/1",
    case: "docs",
    note: "",
    contractsCommit: "",
    ids: {},
    steps: [],
    calls: [],
    wallet: [],
  } as never;
  const fixtureSrc = readFileSync(join(ROOT, "packages/fixture/src/index.ts"), "utf8");
  return {
    efs: new Set(Object.keys(efs).filter((k) => !k.startsWith("_"))),
    lens: new Set(Object.keys(efs.lens)),
    writer: new Set(Object.keys(writer)),
    other: new Set([
      ...Object.keys(openJournal(efs, { journal: memoryJournal() })),
      ...Object.keys(createReplay(transcript)),
      ...Object.keys(createRpcReplay(transcript)),
      ...Object.keys(createRecorder((async () => ({})) as never)),
      ...[...fixtureSrc.matchAll(/^export\s+(?:async\s+)?function\s+(\w+)/gm)].map(
        (m) => m[1] as string,
      ),
    ]),
  };
}

/** Names the docs write as calls that are not SDK APIs, with what each is. */
const NOT_SDK: Readonly<Record<string, string>> = {
  fold: "the caller's fold step (a FoldStep passed as `fold`)",
  onProgress: "an option callback of runSequence and resume",
  request: "the EIP-1193 provider method",
  return: "the async iterator method that stops a stream",
  cancel: "the ReadableStream method that stops a stream",
  resolveMode: "the ERC-5219 contract function",
  realmOrigin: "the contracts' Realm origin derivation",
  max: "arithmetic in the planning rule",
  BIND: "an action, in the protocol's notation",
};

describe("every export is documented", () => {
  it("api-0.1's export index is current (run `node tools/api-index.mjs write`)", () => {
    const doc = readFileSync(API_DOC, "utf8");
    expect(withIndex(doc, renderIndex(index)) === doc).toBe(true);
  });

  it("every function and constant has a JSDoc summary", () => {
    const missing = Object.entries(index).flatMap(([entry, rows]) =>
      rows.filter((r) => isValue(r.kind) && !r.summary).map((r) => `${entry}: ${r.name}`),
    );
    expect(missing).toEqual([]);
  });
});

describe("every API the docs name exists", () => {
  it("imports from @efs/sdk entry points in the docs' code", () => {
    const wrong: string[] = [];
    for (const { path, text } of docs)
      for (const m of text.matchAll(
        /import\s+(?:type\s+)?\{([^}]*)\}\s+from\s+["'](@efs\/sdk(?:\/[\w/]+)?)["']/g,
      )) {
        const entry = m[2] as string;
        const names = (m[1] as string)
          .split(",")
          .map(
            (s) =>
              s
                .trim()
                .replace(/^type\s+/, "")
                .split(/\s+as\s+/)[0] as string,
          )
          .filter(Boolean);
        for (const n of names)
          if (!exported(entry).has(n)) wrong.push(`${path}: ${n} from ${entry}`);
      }
    expect(wrong).toEqual([]);
  });

  it("the README's entry-point table names only what each entry point exports", () => {
    const text = docs.find((d) => d.path === "packages/sdk/README.md")?.text ?? "";
    const wrong: string[] = [];
    let rows = 0;
    for (const m of text.matchAll(/^\| `(@efs\/sdk(?:\/[\w/]+)?)` \| (.*) \|$/gm)) {
      rows++;
      const entry = m[1] as string;
      for (const n of (m[2] as string).matchAll(/`([A-Za-z_$][\w$]*)`/g))
        if (!exported(entry).has(n[1] as string)) wrong.push(`${entry}: ${n[1]}`);
    }
    expect(rows).toBeGreaterThan(8);
    expect(wrong).toEqual([]);
  });

  it("efs.…, efs.lens.… and writer.… members, and every name(…) in inline code", async () => {
    const m = await members();
    const known = new Set([...allExports, ...m.efs, ...m.lens, ...m.writer, ...m.other]);
    const wrong: string[] = [];
    for (const { path, text } of docs) {
      // A quoted "efs.…" is a result's `kind` (e.g. "efs.plan"), not a member.
      for (const x of text.matchAll(
        /(?<![\w"'.-])efs\.([A-Za-z_$][\w$]*)(?:\.([A-Za-z_$][\w$]*))?(?!["'])/g,
      )) {
        const [first, second] = [x[1] as string, x[2]];
        if (first === "lens" && second) {
          if (!m.lens.has(second)) wrong.push(`${path}: efs.lens.${second}`);
        } else if (!m.efs.has(first)) wrong.push(`${path}: efs.${first}`);
      }
      for (const x of text.matchAll(/\bwriter\.([A-Za-z_$][\w$]*)/g))
        if (!m.writer.has(x[1] as string)) wrong.push(`${path}: writer.${x[1]}`);
      for (const x of text.matchAll(/`([A-Za-z_$][\w$]*)\(/g)) {
        const n = x[1] as string;
        if (!known.has(n) && !(n in NOT_SDK)) wrong.push(`${path}: ${n}(…)`);
      }
    }
    expect([...new Set(wrong)]).toEqual([]);
  });
});
